import java.io.*;
import java.util.*;

class Solution {
    public int[] processQueries(int[] queries, int m) {
        int size = 2 * m + 2;
        int[] bit = new int[size];
        int[] position = new int[m + 1];
        int front = m;

        for (int value = 1; value <= m; value++) {
            position[value] = m + value;
            add(bit, position[value], 1);
        }

        int[] answer = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            int value = queries[i];
            int pos = position[value];
            answer[i] = prefix(bit, pos - 1);
            add(bit, pos, -1);
            position[value] = front;
            add(bit, front, 1);
            front--;
        }
        return answer;
    }

    private void add(int[] bit, int i, int delta) {
        while (i < bit.length) {
            bit[i] += delta;
            i += i & -i;
        }
    }

    private int prefix(int[] bit, int i) {
        int total = 0;
        while (i > 0) {
            total += bit[i];
            i -= i & -i;
        }
        return total;
    }
}

