        int front = m;

        auto add = [&](int i, int delta) {
            while (i < (int)bit.size()) {
                bit[i] += delta;
                i += i & -i;
            }
        };
        auto prefix = [&](int i) {
            int total = 0;
            while (i > 0) {
                total += bit[i];
                i -= i & -i;
            }
            return total;
        };

        for (int value = 1; value <= m; value++) {
            position[value] = m + value;
            add(position[value], 1);
        }

        vector<int> answer;
