        int value = queries[k];
        int pos = position[value];
        int rank = 0;
        for (int i = pos - 1; i > 0; i -= i & -i) rank += bit[i];
        result[k] = rank;

        for (int i = pos; i < size; i += i & -i) bit[i]--;
        position[value] = front;
        for (int i = front; i < size; i += i & -i) bit[i]++;
        front--;
    }

    free(bit);
    free(position);
    *returnSize = queriesSize;
    return result;
}

